'use strict';
const $ = id => document.getElementById(id);
const state = {csrf:null, schema:null, current:null, epoch:0, busy:false};
const labels = {load_id:'Synthetic load or container alias',move_id:'Synthetic move alias',move_type:'Terminal move type',terminal_id:'Destination terminal',subject_role:'Person being assessed',driver_id:'Synthetic driver alias',vehicle_id:'Synthetic truck alias',trailer_id:'Synthetic trailer alias',current_sealink_id:'Synthetic SeaLink alias',trip_at:'Trip date and time',gross_weight:'Loaded gross weight',height:'Loaded height',width:'Loaded width',overall_length:'Overall length',semitrailer_length:'Semitrailer length',axle_weights:'Legacy axle or group weights',axle_spacings:'Legacy axle spacings',axle_layout:'Individual axle layout',twic_reported:'TWIC reported',induction_reported:'Induction reported',question_scope:'What are we checking?'};
const names={facility_apm_elizabeth:'APM Elizabeth',synthetic_other_terminal:'Other terminal (synthetic)',truck_driver:'Truck driver',other:'Other',unknown:'Unknown',trip_dispatch:'The whole move / dispatch',terminal_entry:'Terminal entry',route:'Route',induction:'Induction only',path_a_exit13a_to_apm:'Study route: Exit 13A to APM',path_b_us1_9_to_apm:'Study route: US 1/9 to APM'};
function label(s){return labels[s]||s.replaceAll('_',' ').replace(/^./, c=>c.toUpperCase());}
function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
function button(text,fn,cls){const n=el('button',text,cls);n.type='button';n.addEventListener('click',()=>run(fn));return n;}
function notice(text){$('notice').textContent=text||'';$('notice').hidden=!text;}
async function api(path,body){const response=await fetch(path,{method:body===undefined?'GET':'POST',credentials:'same-origin',cache:'no-store',headers:body===undefined?{}:{'Content-Type':'application/json','X-CSRF-Token':state.csrf||''},body:body===undefined?undefined:JSON.stringify(body)});const result=await response.json();if(!response.ok)throw new Error(result.error||'Request unavailable');return result;}
async function run(fn){if(state.busy)return;state.epoch++;state.busy=true;notice('');document.querySelectorAll('button').forEach(n=>n.disabled=true);try{await fn();}catch(e){notice(e.message);if(state.current){$('trip').replaceChildren(el('h1','Reload this conversation'),el('p','The request did not complete normally. Its saved state may have changed; reload before reviewing a result.'),button('Reload conversation',()=>openTrip(state.current.conversation.id)));}}finally{state.busy=false;document.querySelectorAll('button').forEach(n=>n.disabled=false);}}
async function session(){const user=await api('/api/session');state.csrf=user.csrf;state.schema=user.fact_schema.properties;$('identity').textContent=`${user.user_id} · ${user.role}`;$('login').hidden=true;$('workspace').hidden=false;$('logout').hidden=false;await list();}
async function list(){const trips=await api('/api/conversations');$('trips').replaceChildren(...trips.map(t=>button(t.title,()=>openTrip(t.id),state.current?.conversation.id===t.id?'active':'')));}
async function openTrip(id){const epoch=++state.epoch;$('trip').replaceChildren(el('p','Checking this conversation and its current evidence…'));state.current=null;const view=await api('/api/conversations/'+id);if(epoch!==state.epoch)return;state.current=view;render(view);await list();}
function details(title,content){const n=el('details');n.append(el('summary',title),content);return n;}
function itemList(values){const n=el('ul');for(const value of values)n.append(el('li',value));return n;}
function select(options,value){const n=el('select');for(const [v,text] of options){const o=el('option',text);o.value=v;n.append(o);}n.value=value;return n;}
function display(v){if(v===null||v===undefined)return 'Unknown';if(typeof v==='boolean')return v?'Reported yes':'Reported no';if(typeof v==='object')return JSON.stringify(v);return names[v]||String(v);}
function factsTable(facts){const table=el('table');const head=el('tr');head.append(el('th','Reported fact'),el('th','Saved value'));table.append(head);for(const [key,record] of Object.entries(facts||{})){const row=el('tr');row.append(el('td',label(key)),el('td',display(record.value)+(record.unit?' '+record.unit:'')));table.append(row);}return table;}
function fieldControl(key,value){const box=el('div',undefined,'fact-row'), name=el('label',label(key));const schema=state.schema[key].anyOf?.[0]||state.schema[key];let read;
if(key==='axle_layout'){
const rows=el('div'),entries=[];name.append(rows);box.append(el('p','One row per individual axle, front to back. Position is measured from the first axle (zero), not from the preceding axle. Group weights cannot substitute. Remove all rows to leave this unknown.','help'));
function addAxle(v){if(entries.length>=32){notice('At most 32 individual axles are supported.');return;}const row=el('div',undefined,'quantity'),pos=el('input'),weight=el('input');for(const input of [pos,weight]){input.type='number';input.step='any';input.min='0';}pos.value=v?.position?.value??(entries.length===0?'0':'');weight.value=v?.weight?.value??'';pos.setAttribute('aria-label','Position from first axle');weight.setAttribute('aria-label','Individual axle weight');const remove=el('button','Remove axle');remove.type='button';const positionUnit=select([['in','in'],['ft','ft']],v?.position?.unit||'in'),weightUnit=select([['lb','lb'],['kg','kg']],v?.weight?.unit||'lb');positionUnit.setAttribute('aria-label','Axle position unit');weightUnit.setAttribute('aria-label','Individual axle weight unit');const entry={row,pos,weight,positionUnit,weightUnit};remove.addEventListener('click',()=>{entries.splice(entries.indexOf(entry),1);row.remove();});row.append(pos,positionUnit,weight,weightUnit,remove);rows.append(row);entries.push(entry);}
for(const row of value?.axles||[])addAxle(row);const add=el('button','Add individual axle');add.type='button';add.addEventListener('click',()=>addAxle());name.append(add);
read=()=>entries.length?{axles:entries.map(({pos,weight,positionUnit,weightUnit})=>{if(pos.value===''||weight.value===''||!Number.isFinite(Number(pos.value))||!Number.isFinite(Number(weight.value)))throw new Error('Each individual axle needs a position and weight.');return {position:{value:Number(pos.value),unit:positionUnit.value},weight:{value:Number(weight.value),unit:weightUnit.value}};})}:null;
}
else if(schema.type==='boolean'){const n=select([['','Unknown'],['true','Reported yes'],['false','Reported no']],value===null?'':String(value));name.append(n);read=()=>n.value===''?null:n.value==='true';}
else if(schema.enum){const n=select([['','Unknown'],...schema.enum.map(v=>[v,names[v]||label(v)])],value??'');name.append(n);read=()=>n.value||null;}
else if(schema.type==='object'){const group=el('div',undefined,'quantity'),n=el('input');n.type='number';n.min='0';n.step='any';n.value=value?.value??'';n.setAttribute('aria-label',label(key)+' value');const unit=select(schema.properties.unit.enum.map(v=>[v,v]),value?.unit||schema.properties.unit.enum[0]);unit.setAttribute('aria-label',label(key)+' unit');group.append(n,unit);name.append(group);read=()=>n.value===''?null:{value:Number(n.value),unit:unit.value};}
else if(schema.type==='array'){const n=el('input');n.placeholder='Example: 12000, 34000, 34000';n.value=Array.isArray(value)?value.map(v=>v.value).join(', '):'';const unit=select(schema.items.properties.unit.enum.map(v=>[v,v]),value?.[0]?.unit||schema.items.properties.unit.enum[0]);const group=el('div',undefined,'quantity');group.append(n,unit);name.append(group);box.append(el('p','Legacy array: entries can describe axle groups. They are never treated as individual axles. For individual measurements use Individual axle layout. Enter values in order with one unit.','help'));read=()=>n.value.trim()?n.value.split(',').map(v=>{if(!v.trim()||!Number.isFinite(Number(v)))throw new Error('Enter valid numbers for '+label(key));return {value:Number(v),unit:unit.value};}):null;}
else{const n=el('input');n.value=value??'';n.type=schema.type==='integer'?'number':'text';if(schema.type==='integer'){n.step='1';n.min=schema.minimum;n.max=schema.maximum;}if(key.endsWith('_at')){n.placeholder='2026-09-12T14:00:00-04:00';box.append(el('p','Use the exact date, time and timezone supplied. Leave unknown if any part is missing.','help'));}name.append(n);read=()=>n.value.trim()===''?null:schema.type==='integer'?Number(n.value):n.value;}
box.prepend(name);return {box,read};}
function review(view){const card=el('section',undefined,'card');card.append(el('p','02 / REVIEW','eyebrow'),el('h2','Check what was captured'),el('p','Compare these suggestions with your original statement. Correct any value before confirming. Confirmation records what you report; it does not verify a measurement, credential or approval.'));
if(Object.keys(view.prior_reported_facts||{}).length){const prior=details('Previous reports for this move — review what will carry forward',factsTable(view.prior_reported_facts));prior.open=true;card.append(prior);}
const p=view.proposals[0];if(!p){card.append(el('p','No current proposal is available. Reload, or send a new statement to continue.'));return card;}
card.append(el('p',p.origin==='model_proposal'?'Suggested by the connected model.':'Suggested by the bounded local extractor. Unrecognized details must be added below.','small muted'));
if(p.issues.length)card.append(itemList(p.issues.map(i=>`${label(i.field)}: ${i.message}`)));
const form=el('form'),grid=el('div',undefined,'review-grid'),controls=new Map();function add(key,value=null){if(controls.has(key))return;const c=fieldControl(key,value);controls.set(key,c);grid.append(c.box);}
for(const [key,value] of Object.entries(p.facts))add(key,value);
const addRow=el('div',undefined,'form-actions');const picker=select([['','Add a missing reported fact…'],...Object.keys(state.schema).map(v=>[v,label(v)])],'');picker.setAttribute('aria-label','Choose a fact to add');picker.addEventListener('change',()=>{if(picker.value)add(picker.value);picker.value='';});addRow.append(picker);
const scopeLabel=el('label','What do you need checked?','scope');const scope=select(['trip_dispatch','terminal_entry','route','induction','unknown'].map(v=>[v,names[v]]),view.prior_scope||view.case?.question_scope||'trip_dispatch');scopeLabel.append(scope);
const checkLabel=el('label',undefined,'check'),checked=el('input');checked.type='checkbox';checked.required=true;checkLabel.append(checked,el('span','I compared the listed facts with my statement and confirm these reported values, including any corrections I made.'));
const submit=el('button','Confirm facts and assess →','primary');submit.type='submit';form.append(scopeLabel,grid,addRow,el('p','Only listed fields are updated. Other reports remain unless an assignment change invalidates them. Start a new trip for a different move.','help'),checkLabel,submit);
form.addEventListener('submit',e=>{e.preventDefault();run(async()=>{if(!checked.checked)throw new Error('Review and confirm the facts first.');const facts={};for(const [key,c]of controls)facts[key]=c.read();const cid=view.conversation.id;const result=await api(`/api/conversations/${cid}/confirm`,{proposal_id:p.id,version:view.conversation.version,facts,scope:scope.value});state.current=result;render(result);await list();});});card.append(form);return card;}
function reportedChecks(a){const section=el('section',undefined,'card');const pkg=a.reported_fact_checks;if(!pkg)return el('div');section.append(el('h2','What the reported facts show'),el('p','Draft comparisons against retained source text. A value at or below a reference does not establish trip eligibility or permission.'));
if(pkg.status!=='available'){section.append(el('p','Comparisons are unavailable because the evidence or its source mapping needs review. No earlier comparison is reused.'));return section;}
if(!pkg.checks.length)return el('div');const sourceMap=new Map(a.evidence_package.sources.map(s=>[s.clause_id,s]));const order={input_review_required:0,source_review_required:1,attention_required:2,comparison_only:3,reported_unverified:4,manual_review_required:5,missing_facts:6};
for(const c of [...pkg.checks].sort((x,y)=>order[x.status]-order[y.status])){const content=el('div');content.append(el('p',c.summary),el('p',c.context,'small muted'),el('p',`Next action (${c.owner}): ${c.next_action}`));for(const id of c.source_clause_ids){const source=sourceMap.get(id);if(source)content.append(el('p',`Supporting source: ${source.title} · ${source.provenance_review?.recommended_locator||source.locator}`,'small'));}if(!c.source_clause_ids.length)content.append(el('p','No retained governing clause is available.','small'));const detail=details(`${c.title} · ${label(c.status)}`,content);detail.open=['attention_required','input_review_required','source_review_required'].includes(c.status);section.append(detail);}return section;}
function assessment(view){const a=view.assessment;const result=el('section');if(!a)return result;const brief=a.decision_brief;const banner=el('div',undefined,'card status');banner.append(el('p','03 / ASSESSMENT','eyebrow'),el('h2',brief.headline),el('p',brief.summary),el('p','Operational permission: not issued.','permission'));banner.append(el('p','Assessment snapshot: '+new Date(view.assessed_at*1000).toLocaleString()+'. Refresh after changes; this result is not a live gate or route status.','small'));if(brief.next_steps.length)banner.append(el('h3','What to resolve next'),itemList(brief.next_steps));result.append(banner,reportedChecks(a));
const layout=a.input_review.axle_layout;if(layout&&layout.status!=='not_supplied'){const box=el('section',undefined,'card');box.append(el('h2','Individual axle report'),el('p',label(layout.status)));if(layout.axle_count!==null)box.append(el('p',`${layout.axle_count} individual axles · reported total ${layout.total_weight_lb} lb · first-to-last span ${layout.span_inches} in`));box.append(itemList(layout.issues.map(i=>i.message)),el('p','These totals reconcile reports. See the separate requirement findings for verified measurements and executed bridge predicates; report totals alone establish neither.','small'));result.append(box);}
const facts=el('section',undefined,'card');facts.append(el('h2','Confirmed reports'),el('p','Confirmed in this workspace by '+view.confirmation.confirmed_by+'. These are reported facts; independent synthetic verification, where available, is shown separately below.'),factsTable(a.case.facts));result.append(facts);
const evidence=el('section',undefined,'card');evidence.append(el('h2','Findings and supporting evidence'),el('p','Each finding applies to its stated scope. Archived material and dated observations do not establish current operating conditions.'));
const table=el('table');const head=el('tr');head.append(el('th','Requirement'),el('th','Result'),el('th','Evaluation'));table.append(head);for(const f of a.findings){const row=el('tr');row.append(el('td',f.label),el('td',label(f.status)),el('td',label(f.execution_state)));table.append(row);}evidence.append(table);
for(const f of a.findings){if(f.checks?.length){const content=el('div');content.append(itemList(f.checks.map(c=>`${label(c.status)} · ${c.detail}`)),itemList(f.limits));if(f.rejected_evidence?.length)content.append(el('p','Some verification records were rejected; their reasons remain in the assessment record.'));evidence.append(details(f.label+' · predicate details',content));}}
for(const s of a.evidence_package.draft_supplements||[]){const content=el('div');content.append(el('p',`${s.publisher} · ${s.locator}`),el('pre',s.source_text),el('p',s.interpretation_boundary),el('p','Draft extraction from the graph-linked archived document. Awaiting source and policy review.'));evidence.append(details('Draft source supplement · '+s.title,content));}
for(const source of a.evidence_package.sources){const content=el('div');const locator=source.provenance_review?.recommended_locator||source.locator;content.append(el('p',`${source.publisher} · ${locator}`),el('p',`Published: ${source.publication_date} · Accessed: ${source.accessed_date}`),el('p',source.currentness));const u=String(source.url||'');if(/^https?:\/\//.test(u)){const link=el('a','Open source');link.href=u;link.target='_blank';link.rel='noopener noreferrer';content.append(link);}const text=source.source_text;content.append(el('pre',typeof text==='string'?text:JSON.stringify(text,null,2)));if(source.provenance_review)content.append(el('p',source.provenance_review.note));const d=details(source.title,content);d.className='source';evidence.append(d);}
for(const o of a.evidence_package.observations)evidence.append(details('Dated operating observation — currentness unverified',el('pre',JSON.stringify(o.record,null,2))));evidence.append(itemList(a.coverage.gaps.map(label)));result.append(evidence);return result;}
function management(view){const box=el('div',undefined,'card');if(view.is_owner){const form=el('form');form.append(el('h3','Share this conversation'));const user=el('input');user.placeholder='syn-user-dispatch';user.required=true;user.setAttribute('aria-label','Synthetic user to share with');const permission=select([['view','Can view'],['edit','Can review and update'],['remove','Remove access']],'view');const row=el('div',undefined,'form-actions');const save=el('button','Update access');save.type='submit';row.append(permission,save);form.append(user,row);form.addEventListener('submit',e=>{e.preventDefault();run(async()=>{await api(`/api/conversations/${view.conversation.id}/share`,{user_id:user.value,permission:permission.value});notice('Conversation access updated.');});});box.append(form);}
if(view.can_edit){box.append(el('h3','Optional model proposals'));box.append(el('p','A one-hour connection key lets the restricted MCP bridge read the latest statement and propose facts for this conversation. User confirmation stays here.','small'));const output=el('pre');box.append(button('Create proposal connection key',async()=>{const r=await api(`/api/conversations/${view.conversation.id}/capability`,{});output.textContent=r.capability;notice('Connection key shown once on this page. Save it to a private file for the bridge; do not paste it into a model conversation.');}),button('Create proposal and confirmed-assessment key',async()=>{const r=await api(`/api/conversations/${view.conversation.id}/assessment-capability`,{});output.textContent=r.capability;notice('This one-hour key can propose facts and read this conversation’s confirmed reports and fresh assessment. It cannot confirm facts. Save privately; do not paste it into chat.');}),el('p','The assessment key additionally shares the original statements, confirmed reports and assessment for this conversation. Existing proposal keys keep proposal-only access.','small'),output);}
if(view.is_owner){box.append(button('Revoke model access',async()=>{await api(`/api/conversations/${view.conversation.id}/revoke-capabilities`,{});notice('All model keys for this conversation were revoked.');}));box.append(el('hr'));const label=el('label',undefined,'check'),check=el('input');check.type='checkbox';label.append(check,el('span','Delete this conversation and its saved case. Older backups and hash-only audit records remain.'));box.append(label,button('Delete conversation',async()=>{if(!check.checked)throw new Error('Select the deletion checkbox first.');await api(`/api/conversations/${view.conversation.id}/delete`,{version:view.conversation.version});state.current=null;$('trip').replaceChildren(el('h1','Conversation deleted'));await list();},'danger'));}return details('Sharing and conversation controls',box);}
function render(view){const root=$('trip');root.replaceChildren();const head=el('div',undefined,'trip-head');const title=el('div');title.append(el('p','TRIP CONVERSATION','eyebrow'),el('h1',view.conversation.title));head.append(title,button('Refresh assessment',()=>openTrip(view.conversation.id)));root.append(head);
if(view.messages.length){const section=el('section',undefined,'card');section.append(el('h2','Original statements'));for(const m of view.messages){const row=el('div',undefined,'message');row.append(el('div',m.author+' · '+new Date(m.created*1000).toLocaleString(),'message-meta'),el('div',m.body));section.append(row);}root.append(section);}
if(view.assessment)root.append(assessment(view));else if(view.messages.length){if(view.can_edit)root.append(review(view));else root.append(el('p','The latest statement is awaiting confirmation by a user with edit access. No previous assessment is displayed.','card status'));}
if(view.can_edit){const form=el('form',undefined,'card');form.append(el('p','01 / DESCRIBE','eyebrow'),el('h2',view.messages.length?'Add a detail or correction':'Describe the move'));const label=el('label','What should we know about this trip?');const text=el('textarea');text.placeholder='Can I take this truck to APM? Gross weight 80,000 lb, 14 ft 7 in high. I have…';text.maxLength=8000;text.required=true;label.append(text);const row=el('div',undefined,'form-actions');row.append(el('span','Use synthetic details only. A new statement pauses the prior assessment.','help'));const submit=el('button','Save statement and review →','primary');submit.type='submit';row.append(submit);form.append(label,row);let key=null,submitted=null;form.addEventListener('submit',e=>{e.preventDefault();run(async()=>{if(submitted!==text.value){key=crypto.randomUUID();submitted=text.value;}const cid=view.conversation.id;$('trip').replaceChildren(el('h1','Saving statement for review…'));const r=await api(`/api/conversations/${cid}/message`,{version:view.conversation.version,statement:text.value,request_key:key});state.current=r;render(r);await list();});});root.append(form);}root.append(management(view));}
$('login-form').addEventListener('submit',e=>{e.preventDefault();run(async()=>{await api('/api/login',{key:$('access-key').value});$('access-key').value='';await session();});});
$('logout').addEventListener('click',()=>run(async()=>{await api('/api/logout',{});state.epoch++;state.current=null;state.csrf=null;$('workspace').hidden=true;$('login').hidden=false;$('logout').hidden=true;$('identity').textContent='';$('trip').replaceChildren();}));
$('new-trip').addEventListener('click',()=>run(async()=>{const r=await api('/api/conversations',{});await openTrip(r.id);}));
// Background refresh removes results that became stale in another conversation
// participant's session. Never interrupt a fact review being edited.
setInterval(async()=>{if(state.busy||!state.current?.assessment||document.hidden)return;const cid=state.current.conversation.id,epoch=state.epoch;try{const r=await api('/api/conversations/'+cid);if(epoch===state.epoch&&state.current?.conversation.id===cid&&!state.busy){state.current=r;render(r);}}catch(e){if(epoch===state.epoch){state.current=null;$('trip').replaceChildren(el('h1','Assessment unavailable'),el('p','Access or saved state may have changed. Reopen the conversation to continue.'));}}},30000);
session().catch(()=>{});
